      "inputs": {
        "script": "const fields = $vars.extractInvoiceFields.output.ExtractionResult.ResultsDocument.Fields || [];\nconst find = name => fields.find(f => f.FieldName === name)?.Values?.[0] || null;\nreturn {\n  vendorName: find('VendorName'),\n  invoiceNumber: find('InvoiceNumber'),\n  invoiceDate: find('InvoiceDate'),\n  totalAmount: find('TotalAmount'),\n  lineItems: ($vars.extractInvoiceFields.output.ExtractionResult.ResultsDocument.Tables || [])\n};"
      },
